import re
import unittest
from pathlib import Path

from textkit.cli import COMMANDS

README = Path(__file__).resolve().parent.parent / "README.md"


def readme_rows():
    rows = {}
    for line in README.read_text().splitlines():
        m = re.match(r"^\|\s*`([^`]+)`\s*\|(.*)\|\s*$", line)
        if m:
            rows[m.group(1)] = m.group(2).strip()
    return rows


class DocSyncTest(unittest.TestCase):
    def test_readme_matches_help(self):
        rows = readme_rows()
        for name, c in COMMANDS.items():
            with self.subTest(command=name):
                self.assertIn(name, rows, "missing README row")
                self.assertEqual(rows[name], c["help"])

    def test_no_unregistered_rows(self):
        self.assertEqual(set(readme_rows()) - set(COMMANDS), set())


if __name__ == "__main__":
    unittest.main()
